input.command:
cd /tmp && mkdir -p pfv && cat > pfv/in.txt <<'TXT'
Here is an example command:
```bash
echo hi
```
PLAN_YAML:
```yaml
decisions:
  - Decision A
plan:
  steps:
    - Step A
```
TXT
new_extract() {
  local f="$1" extracted
  extracted="$(awk '
    !found && /^```/ { fence_before_marker=1 }
    /^PLAN_YAML:/ && !fence_before_marker { found=1; next }
    found && !in_fence && /^```/ { in_fence=1; next }
    in_fence && /^```/ { exit }
    in_fence { print }
  ' "$f" 2>/dev/null)"
  if [[ -n "${extracted}" ]]; then printf '%s\n' "${extracted}"; return 0; fi
  extracted="$(awk '
    !in_fence && /^```/ { in_fence=1; next }
    in_fence && /^```/ { exit }
    in_fence && /^PLAN_YAML:/ { seen_marker=1; next }
    in_fence && seen_marker { print }
  ' "$f" 2>/dev/null)"
  if [[ -n "${extracted}" ]]; then printf '%s\n' "${extracted}"; return 0; fi
  if ! awk '/^```/ { found=1 } END { exit !found }' "$f" 2>/dev/null \
      && awk '/^PLAN_YAML:/ { found=1 } END { exit !found }' "$f" 2>/dev/null; then
    awk 'found { print } /^PLAN_YAML:/ { found=1 }' "$f" 2>/dev/null; return 0
  fi
  cat "$f" 2>/dev/null
}
old_extract() {
  local f="$1" extracted
  extracted="$(awk '
    /^PLAN_YAML:/ { found=1; next }
    found && /^```/ { fence++ ; if (fence==1) next; exit }
    found { print }
  ' "$f" 2>/dev/null)"
  if [[ -n "${extracted}" ]]; then printf '%s\n' "${extracted}"; else cat "$f" 2>/dev/null; fi
}
echo "=== NEW ==="; new_extract pfv/in.txt
echo "=== OLD ==="; old_extract pfv/in.txt
